package io.github.chronicle.core.server;

import io.github.chronicle.core.authoring.AuthoringSite;
import io.github.chronicle.core.encounters.*;
import io.github.chronicle.core.menu.CoreMenuModel.*;
import io.github.chronicle.core.menu.EncounterEditorForm;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.network.ServerPlayerEntity;

import java.io.IOException;
import java.util.*;

/** Server-authoritative encounter list/editor projection and finite selector catalogs. */
final class CoreEncounterMenu {
    private CoreEncounterMenu(){ }

    static List<Entry> entries(MinecraftServer server){var snapshot=Encounters.snapshot(server);return snapshot.groups().values().stream().map(group->entry(group.id(),group.label(),group.description(),"ENCOUNTER",group.id(),snapshot.groupRevision())).toList();}
    static EncounterEditorForm empty(MinecraftServer server){var snapshot=Encounters.snapshot(server);String id="chronicle_core:encounter_"+UUID.randomUUID().toString().replace("-","").substring(0,12);return new EncounterEditorForm(snapshot.groupRevision(),snapshot.bindingRevision(),id,"","",List.of(),"","","",0,false,"",true);}
    static EncounterEditorForm form(MinecraftServer server,String id,boolean creating){if(creating)return empty(server);var snapshot=Encounters.snapshot(server);EncounterGroup group=snapshot.groups().get(id);if(group==null)throw new IllegalArgumentException("Choose an encounter group");EncounterBinding binding=snapshot.bindings().get(id);List<EncounterEditorForm.Member> members=group.members().stream().map(member->new EncounterEditorForm.Member(member.entityType(),member.entityType(),member.count(),Encounters.entityTypes().contains(member.entityType()),Encounters.entityTypes().contains(member.entityType())?"":"Entity type is no longer allowed.")).toList();String kind="",siteId="",label="",problem="Choose a Point or Region target.";long revision=0;boolean current=false;if(binding!=null){kind=binding.target().kind().name();siteId=binding.siteId();revision=binding.siteRevision();AuthoringSite site=AuthoringRuntime.get(server).service().state().sites().get(siteId);label=siteId;current=site!=null&&site.revision()==revision&&(kind.equals("POINT")&&site instanceof AuthoringSite.Location||kind.equals("REGION")&&site instanceof AuthoringSite.Region);problem=current?"":"Map target is missing, changed or has the wrong kind.";}return new EncounterEditorForm(snapshot.groupRevision(),snapshot.bindingRevision(),group.id(),group.label(),group.description(),members,kind,siteId,label,revision,current,problem,false);}
    static Detail detail(ServerPlayerEntity player,String selected){MinecraftServer server=player.getEntityWorld().getServer();boolean editable=player.getCommandSource().hasPermissionLevel(2)&&AuthoringRuntime.isAuthor(player)&&AuthoringRuntime.editable(server)&&RuntimeHolds.reason(server)==null;String reason=RuntimeHolds.reason(server)!=null?"Finish pending operations before editing encounter groups.":"Pause play and enable Editing to change encounter groups.";List<Control> controls=new ArrayList<>();controls.add(control(Action.ENCOUNTER_NEW,"Create encounter group",editable,reason,false,""));if(selected==null||selected.isBlank())return new Detail("","Encounter groups","Reusable bounded mob compositions. Map Points and Regions remain world-owned.",List.of(),controls,null,null,null);var snapshot=Encounters.snapshot(server);EncounterGroup group=snapshot.groups().get(selected);if(group==null)throw new IllegalArgumentException("Choose an encounter group");EncounterBinding binding=snapshot.bindings().get(selected);List<Fact> facts=new ArrayList<>();facts.add(new Fact("Group ID",group.id()));facts.add(new Fact("Members",group.members().stream().map(member->member.entityType()+" × "+member.count()).reduce((a,b)->a+"; "+b).orElse("None")));facts.add(new Fact("Total entities",Integer.toString(group.entityCount())));facts.add(new Fact("Map binding",binding==null?"Missing":binding.targetKind()+" "+binding.siteId()+" @ "+binding.siteRevision()));long uses=EventRuntime.configurations(server).values().stream().flatMap(value->value.definition().encounterActions().stream()).filter(action->action.groupId().equals(group.id())).count();facts.add(new Fact("Event uses",Long.toString(uses)));controls.add(control(Action.ENCOUNTER_EDIT,"Edit group",editable,reason,false,""));controls.add(control(Action.ENCOUNTER_DELETE,"Delete group",editable&&uses==0,uses>0?"Remove this group from every Event first.":reason,true,""));return new Detail(group.id(),group.label(),group.description(),facts,controls,null,null,null);}
    static EncounterGroup save(ServerPlayerEntity player,EncounterEditorForm form)throws IOException{EncounterGroup group=new EncounterGroup(form.id(),form.label(),form.description(),form.members().stream().map(member->new EncounterMember(member.entityType(),member.count())).toList());if(form.targetKind().isEmpty()||form.siteId().isEmpty()||!form.current())throw new IllegalStateException("Choose a current Point or Region target");EncounterTarget target=new EncounterTarget(EncounterTarget.Kind.valueOf(form.targetKind()),form.siteId(),form.siteRevision());var snapshot=Encounters.snapshot(player.getEntityWorld().getServer());EncounterGroup expected=form.creating()?null:snapshot.groups().get(form.id());EncounterBinding expectedBinding=snapshot.bindings().get(form.id());return Encounters.save(player,group,target,expected,expectedBinding,form.groupRegistryRevision(),form.bindingRegistryRevision());}
    static void delete(ServerPlayerEntity player,String id,long groupRevision,long bindingRevision)throws IOException{var snapshot=Encounters.snapshot(player.getEntityWorld().getServer());EncounterGroup group=snapshot.groups().get(id);if(group==null)throw new IllegalArgumentException("Choose an encounter group");Encounters.delete(player,id,group,snapshot.bindings().get(id),groupRevision,bindingRevision);}
    static List<Entry> catalog(MinecraftServer server,String kind){List<Entry> values=new ArrayList<>();switch(kind){case "ENCOUNTER_ENTITY"->Encounters.entityTypes().forEach(id->values.add(entry(id,id,"Allowed MobEntity; no NBT or commands","ENTITY",id,0)));case "ENCOUNTER_POINT"->AuthoringRuntime.get(server).service().state().sites().values().stream().filter(AuthoringSite.Location.class::isInstance).map(AuthoringSite.Location.class::cast).sorted(Comparator.comparing(AuthoringSite.Location::id)).forEach(site->values.add(entry(site.id(),site.id(),site.dimension()+" · "+site.x()+" "+site.y()+" "+site.z(),"POINT",site.id(),site.revision())));case "ENCOUNTER_REGION"->AuthoringRuntime.get(server).service().state().sites().values().stream().filter(AuthoringSite.Region.class::isInstance).map(AuthoringSite.Region.class::cast).sorted(Comparator.comparing(AuthoringSite.Region::id)).forEach(site->values.add(entry(site.id(),site.id(),site.dimension()+" · "+site.min()+" to "+site.max(),"REGION",site.id(),site.revision())));default->throw new IllegalArgumentException("Unsupported encounter selector: "+kind);}return List.copyOf(values);}
    private static Entry entry(String id,String label,String description,String kind,String reference,long revision){return new Entry(id,shortText(label,160),shortText(description,2048),kind,reference,revision);}private static Control control(Action action,String label,boolean enabled,String reason,boolean confirm,String input){return new Control(action,label,enabled,enabled?"":shortText(reason,512),confirm,input);}private static String shortText(String value,int max){if(value==null)return"";return value.substring(0,Math.min(value.length(),max));}
}
